Fixpoint bm_get4 (l : list bool) (n : nat) {struct n} : bool :=
  match n with
  | S (S (S (S m))) => match l with _ :: _ :: _ :: _ :: r => bm_get4 r m | _ => false end
  | _ => bm_get l n
  end.
Lemma bm_get4_eq : forall n l, bm_get4 l n = bm_get l n.
Proof.
