Definition mkbc_m (fk : list kentry) : bctx :=
  let ffk := facts_of fk in
  let ri := mk_riF ffk in
  BC fk ffk (fst (sum_factsM (BC fk ffk [] ri) ([], []) fk)) ri.
Lemma mkbc_m_eq : forall fk, mkbc_m fk = mkbc fk.
